<?php
require __DIR__.'/includes/bootstrap.php';requireRole('user');$q=$pdo->prepare('SELECT b.*,e.title,e.start_time,e.location,e.status FROM bookings b JOIN events e ON e.event_id=b.event_id WHERE b.user_id=? ORDER BY e.start_time DESC');$q->execute([currentUser()['user_id']]);$bookings=$q->fetchAll();
$q=$pdo->prepare('SELECT w.*,e.title,e.start_time,e.location,e.status,(SELECT COUNT(*) FROM waiting_list w2 WHERE w2.event_id=w.event_id AND (w2.joined_at<w.joined_at OR (w2.joined_at=w.joined_at AND w2.entry_id<=w.entry_id))) AS position FROM waiting_list w JOIN events e ON e.event_id=w.event_id WHERE w.user_id=? ORDER BY e.start_time');$q->execute([currentUser()['user_id']]);$waiting=$q->fetchAll();
$pageTitle='My tickets';require __DIR__.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">GOOD THINGS AHEAD</p><h1>Your plans, in one place.</h1></div><a class="button secondary" href="index.php">Find something new ↗</a></div>
<?php if(!$bookings):?><div class="empty-state"><span>↗</span><h3>Your calendar is a blank canvas.</h3><p>Find an experience and make it yours.</p><a class="button" href="index.php">Discover events</a></div><?php endif;?><ul class="booking-list"><?php foreach($bookings as $b):?><li class="booking-card"><div><span class="status <?=e($b['status'])?>"><?=in_array($b['status'],['removed','cancelled'],true)?'Cancelled':($b['checked_in']?'Checked in':($b['status']==='approved'?'Confirmed':'Awaiting event approval'))?></span><h2><a href="event.php?id=<?=(int)$b['event_id']?>"><?=e($b['title'])?></a></h2><p class="meta"><?=e(date('D j M Y · H:i',strtotime($b['start_time'])))?> · <?=e($b['location'])?></p></div><div class="event-actions"><a class="button secondary" href="booked.php?id=<?=(int)$b['event_id']?>">View ticket ↗</a><?php if(!$b['checked_in']&&strtotime($b['start_time'])>time()):?><form method="post" action="cancel_booking.php" data-confirm="Cancel your booking and release this place?"><?=csrfField()?><input type="hidden" name="booking_id" value="<?=(int)$b['booking_id']?>"><button class="danger small">Cancel booking</button></form><?php endif;?></div></li><?php endforeach;?></ul>
<?php if($waiting):?><div class="section-heading compact"><h2>Your waiting lists</h2></div><ul class="booking-list"><?php foreach($waiting as $w):?><li class="booking-card"><div><p class="eyebrow">POSITION #<?=(int)$w['position']?></p><h2><?=e($w['title'])?></h2><p class="meta"><?=e(date('j M Y · H:i',strtotime($w['start_time'])))?></p></div><form method="post" action="leave_waitlist.php"><?=csrfField()?><input type="hidden" name="event_id" value="<?=(int)$w['event_id']?>"><button class="secondary">Leave waiting list</button></form></li><?php endforeach;?></ul><?php endif;?>
